#include <climits>
#include <functional>
#include <iostream>
#include <queue>
#include <string>
#include <utility>
#include <vector>
using namespace std;

using Edge = pair<int, int>;  // (to, weight)

// Shortest distances from src when every weight is non-negative.
vector<long long> dijkstra(const vector<vector<Edge>>& adj, int src, vector<int>& prev) {
    const long long INF = LLONG_MAX;
    vector<long long> dist(adj.size(), INF);
    prev.assign(adj.size(), -1);
    // Min-heap of (distance, vertex).
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;  // stale entry: u was settled via a shorter path
        for (auto [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                prev[v] = u;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

int main() {
    const char* name = "ABCDEF";
    vector<vector<Edge>> adj(6);
    auto road = [&](int u, int v, int w) {
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    };
    road(0, 1, 4); road(0, 2, 1); road(2, 1, 2); road(1, 3, 5); road(2, 3, 8);
    road(2, 4, 10); road(3, 4, 2); road(3, 5, 6); road(4, 5, 3);

    vector<int> prev;
    vector<long long> dist = dijkstra(adj, 0, prev);
    for (int v = 0; v < 6; ++v) {
        string path;
        for (int x = v; x != -1; x = prev[x]) path = string(1, name[x]) + (path.empty() ? "" : " -> ") + path;
        cout << "A -> " << name[v] << ": " << dist[v] << "  via " << path << "\n";
    }
    return 0;
}

#include <iostream>
#include <queue>
#include <string>
#include <utility>
#include <vector>
using namespace std;

// Kahn's algorithm. Returns a topological order, or an empty vector if there is a cycle.
vector<int> topologicalOrder(int n, const vector<pair<int, int>>& edges) {
    vector<vector<int>> out(n);
    vector<int> indegree(n, 0);
    for (const auto& [from, to] : edges) {
        out[from].push_back(to);
        ++indegree[to];
    }
    queue<int> ready;
    for (int v = 0; v < n; ++v)
        if (indegree[v] == 0) ready.push(v);

    vector<int> order;
    while (!ready.empty()) {
        int u = ready.front();
        ready.pop();
        order.push_back(u);
        for (int v : out[u])
            if (--indegree[v] == 0) ready.push(v);
    }
    if ((int)order.size() < n) return {};  // the leftovers all sit on or behind a cycle
    return order;
}

int main() {
    vector<string> task = {"fetch", "parse", "lint", "typecheck", "bundle", "test", "deploy"};
    // (a, b): a must happen before b
    vector<pair<int, int>> deps = {{0, 1}, {1, 2}, {1, 3}, {3, 4}, {2, 5}, {3, 5}, {4, 6}, {5, 6}};

    vector<int> order = topologicalOrder((int)task.size(), deps);
    cout << "build order:";
    for (int v : order) cout << ' ' << task[v];
    cout << "\n";

    deps.push_back({6, 1});  // "deploy before parse" creates a cycle
    cout << (topologicalOrder((int)task.size(), deps).empty() ? "cycle detected" : "no cycle") << "\n";
    return 0;
}
